add(c,6,'MC',2,'2.potency-efficacy-graph','3종류의 약물이 흰쥐 평활근 수축에 미치는 효과를 측정하여 아래와 같은 그래프를 얻었다. 약물에 관한 설명으로 옳은 것은?',['A가 B와 C보다 효능과 효력이 크다.','B가 A보다 효능이 낮다.','C가 가장 효력이 크다.','A는 B와 효능은 같지만 효력은 크다.','C는 역작용제이다.'],[4],'충돌',[ty(6,'(2) — 답) 줄에 수기 취소선'),hd(6,'④ 에 수기 동그라미 · 정답 줄 취소'),t2('22','6번 보기','④ A는 B와 효능은 같지만 효력은 크다 에 수기 동그라미(22학번 6번, 동형 그림)','hand')],cf=[[SRC['20']+' typed 답)','[2]','수기로 취소선']],cand=[{'n':4,'why':'20학번 수기 동그라미 ④ + 22학번 6번 수기 ④; 그림에서 A·B의 최대반응이 같고 A가 왼쪽(효력 큼)'}],fig='f20_6',conf='중',nt='typed 키 ②와 수기 ④가 충돌. 그림상 A와 B의 plateau가 같음 → ④ 쪽이 그림과 부합(그림 판독, 교안에는 potency 정의 없음).')
add(c,7,'MC',2,'2.TI','와파린의 치료지수 그래프는 아래와 같다. 이 그래프에 대한 설명으로 옳은 것은?',['이 약물은 치료시 부작용이 거의 일어나지 않는다.','이 약물의 치료효과 범위는 작다.','이 약물은 안전하게 사용할 수 있다.','치료지수가 크다.','이 약물의 부작용은 용량과는 관계가 없다.'],[2],'교차확인',[ty(7,'(2)'),t4('tismall')],fig='f20_7',nt='교안 Ch.2 p.19에 같은 그림.')
